import logging

def list(self, target=None, with_deps=False, recursive=False):
    """
    Lists tags in the repository.

    Args:
        target (str, optional): Target directory. Defaults to None.
        with_deps (bool, optional): Include dependencies. Defaults to False.
        recursive (bool, optional): Recurse through directories. Defaults to False.

    Returns:
        dict: Dictionary of tags.
    """
    ret = {}
    try:
        stages = self.collect(target, with_deps=with_deps, recursive=recursive)
        for stage in stages:
            outs_tags = {}
            for out in stage.outs:
                if out.tags:
                    outs_tags[str(out)] = out.tags.copy()
            if outs_tags:
                ret.update({stage.relpath: outs_tags})
        return ret
    except Exception as e:
        logging.error(f"Error listing tags: {e}")
        return {}
